Implement Fibonacci, Cycle, and zip_sum in src/lib.rs.

pub struct Fibonacci { a: u64, b: u64 }
impl Fibonacci {
    pub fn new() -> Self { Fibonacci { a: 0, b: 1 } }
}
impl Iterator for Fibonacci {
    type Item = u64;
    fn next(&mut self) -> Option<u64> {
        let val = self.a;
        let next_b = self.a + self.b;
        self.a = self.b;
        self.b = next_b;
        Some(val) // infinite iterator
    }
}

pub struct Cycle<T: Clone> { items: Vec<T>, index: usize }
impl<T: Clone> Cycle<T> {
    pub fn new(items: Vec<T>) -> Self { Cycle { items, index: 0 } }
}
impl<T: Clone> Iterator for Cycle<T> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        if self.items.is_empty() { return None; }
        let val = self.items[self.index].clone();
        self.index = (self.index + 1) % self.items.len();
        Some(val)
    }
}

